#include <algorithm>
#include <omp.h>

namespace {
constexpr int kSimdLanes = 4;
}

static void mandelbrot_simd_rows(float x0, float y0, float x1, float y1,
                                 int width, int height, int maxIterations,
                                 int output[], int threads) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;
    int requested_threads = threads > 0 ? threads : 1;

    #pragma omp parallel for schedule(static) num_threads(requested_threads)
    for (int j = 0; j < height; ++j) {
        float y = y0 + j * dy;

        for (int base = 0; base < width;) {
            const int lanes = std::min(kSimdLanes, width - base);
            float c_re[kSimdLanes];
            float c_im[kSimdLanes];
            float z_re[kSimdLanes];
            float z_im[kSimdLanes];
            int active[kSimdLanes];
            int counts[kSimdLanes];

            #pragma omp simd
            for (int lane = 0; lane < kSimdLanes; ++lane) {
                active[lane] = 0;
                counts[lane] = maxIterations > 0 ? maxIterations : 0;
                c_re[lane] = 0.0f;
                c_im[lane] = 0.0f;
                z_re[lane] = 0.0f;
                z_im[lane] = 0.0f;

                if (lane < lanes) {
                    const int i = base + lane;
                    c_re[lane] = x0 + i * dx;
                    c_im[lane] = y;
                    z_re[lane] = c_re[lane];
                    z_im[lane] = c_im[lane];
                    active[lane] = 1;
                }
            }

            for (int iter = 0; iter < maxIterations; ++iter) {
                int any_active = 0;
                #pragma omp simd reduction(|:any_active)
                for (int lane = 0; lane < kSimdLanes; ++lane) {
                    if (active[lane]) {
                        if (z_re[lane] * z_re[lane] + z_im[lane] * z_im[lane] > 4.0f) {
                            counts[lane] = iter;
                            active[lane] = 0;
                        } else {
                            float new_re = z_re[lane] * z_re[lane] - z_im[lane] * z_im[lane];
                            float new_im = 2.0f * z_re[lane] * z_im[lane];
                            z_re[lane] = c_re[lane] + new_re;
                            z_im[lane] = c_im[lane] + new_im;
                        }
                        any_active |= active[lane];
                    }
                }
                if (any_active == 0)
                    break;
            }

            #pragma omp simd
            for (int lane = 0; lane < kSimdLanes; ++lane) {
                if (lane < lanes) {
                    const int i = base + lane;
                    output[j * width + i] = counts[lane];
                }
            }

            base += lanes;
        }
    }
}

extern "C" void run(const void* input1, const void* input2, void* output,
                    int n, int parameter, int threads) {
    const float* a = static_cast<const float*>(input1);
    (void)input2;
    mandelbrot_simd_rows(a[0], a[1], a[2], a[3], n * 3 / 2, n,
                         parameter, static_cast<int*>(output), threads);
