48:     // Here |c| < 0.177. If |z| <= 0.25, the exact next magnitude is at most
49:     // |c| + |z|^2 < 0.2395. The recurrence uses only a few operations on
50:     // bounded binary32 values; 32 eps per component is a deliberately wide
51:     // absolute rounding allowance. Even allowing 2 such component errors,
52:     // the next magnitude remains below 0.25, safely below escape radius 2.
53:     const float rounding_margin =
54:         32.0f * std::numeric_limits<float>::epsilon();
55:     return 0.177f + 0.0625f + 2.0f * rounding_margin < 0.25f;
